INSERT INTO `wp_postmeta` VALUES (45,27,'process_1_title','Granos de Café');
INSERT INTO `wp_postmeta` VALUES (46,27,'_process_1_title','field_6a31999d990c0');
INSERT INTO `wp_postmeta` VALUES (47,27,'process_1_description','Todo comienza en el origen: seleccionamos los mejores granos desde su recolección, trabajando con caficultores que cuidan cada detalle del cultivo. Solo elegimos granos maduros, con el aroma y cuerpo ideales para ofrecer un café de alta calidad.');
INSERT INTO `wp_postmeta` VALUES (48,27,'_process_1_description','field_6a3199cc990c1');
INSERT INTO `wp_postmeta` VALUES (49,27,'process_1_image','51');
INSERT INTO `wp_postmeta` VALUES (50,27,'_process_1_image','field_6a319a00990c2');
INSERT INTO `wp_postmeta` VALUES (51,27,'process_1','');
INSERT INTO `wp_postmeta` VALUES (52,27,'_process_1','field_6a319965990bf');
INSERT INTO `wp_postmeta` VALUES (53,27,'process_2_title','Tostar el Café');
INSERT INTO `wp_postmeta` VALUES (54,27,'_process_2_title','field_6a319b1848e16');
INSERT INTO `wp_postmeta` VALUES (55,27,'process_2_description','El tostado es un arte que realizamos con precisión y dedicación. Cada lote de café es tostado en pequeños volúmenes para resaltar sus notas únicas, garantizando un sabor profundo, equilibrado y lleno de carácter.');
INSERT INTO `wp_postmeta` VALUES (56,27,'_process_2_description','field_6a319b1848e17');
INSERT INTO `wp_postmeta` VALUES (57,27,'process_2_image','52');
INSERT INTO `wp_postmeta` VALUES (58,27,'_process_2_image','field_6a319b1848e18');
INSERT INTO `wp_postmeta` VALUES (59,27,'process_2','');
INSERT INTO `wp_postmeta` VALUES (60,27,'_process_2','field_6a319b1848e15');
INSERT INTO `wp_postmeta` VALUES (61,27,'process_3_title','Empacar el Café');
INSERT INTO `wp_postmeta` VALUES (62,27,'_process_3_title','field_6a319b3348e1a');
INSERT INTO `wp_postmeta` VALUES (63,27,'process_3_description','Una vez tostado, empacamos el café de forma cuidadosa para conservar todo su aroma y frescura. Nuestro empaque protege cada grano del aire, la luz y la humedad, asegurando que llegue a ti como recién hecho.');
INSERT INTO `wp_postmeta` VALUES (64,27,'_process_3_description','field_6a319b3348e1b');
INSERT INTO `wp_postmeta` VALUES (65,27,'process_3_image','53');
INSERT INTO `wp_postmeta` VALUES (66,27,'_process_3_image','field_6a319b3348e1c');
INSERT INTO `wp_postmeta` VALUES (67,27,'process_3','');
INSERT INTO `wp_postmeta` VALUES (68,27,'_process_3','field_6a319b3348e19');
INSERT INTO `wp_postmeta` VALUES (69,27,'process_4_title','Moler Granos de Café');
INSERT INTO `wp_postmeta` VALUES (70,27,'_process_4_title','field_6a319b5048e1e');
INSERT INTO `wp_postmeta` VALUES (71,27,'process_4_description','Moler el café en el punto justo es clave para una buena taza. Lo hacemos según el método de preparación: desde prensa francesa hasta espresso, respetando el grano y lo que cada tipo de molienda puede aportar a la experiencia.');
INSERT INTO `wp_postmeta` VALUES (72,27,'_process_4_description','field_6a319b5048e1f');
INSERT INTO `wp_postmeta` VALUES (73,27,'process_4_image','54');
INSERT INTO `wp_postmeta` VALUES (74,27,'_process_4_image','field_6a319b5048e20');
INSERT INTO `wp_postmeta` VALUES (75,27,'process_4','');
INSERT INTO `wp_postmeta` VALUES (76,27,'_process_4','field_6a319b5048e1d');
INSERT INTO `wp_postmeta` VALUES (77,27,'process_5_title','Disfrutar una Taza de Café');
INSERT INTO `wp_postmeta` VALUES (78,27,'_process_5_title','field_6a319b6148e22');
INSERT INTO `wp_postmeta` VALUES (79,27,'process_5_description','Servirte una taza en nuestra cafetería es invitarte a vivir un momento único. Aquí, cada sorbo está lleno de historia, pasión y sabor. Ven y déjate envolver por una experiencia que va más allá del café.');
INSERT INTO `wp_postmeta` VALUES (80,27,'_process_5_description','field_6a319b6148e23');
