INSERT INTO `wp_posts` VALUES (24,1,'2026-06-16 14:45:17','2026-06-16 14:45:17','Desde 1939, el sabor que reúne generaciones\r\n\r\nEn el corazón de la ciudad, nuestra cafetería ha sido testigo de historias, encuentros y momentos memorables desde 1939. Más que un café, ofrecemos una experiencia con alma: aromas que despiertan recuerdos, sabores que reconfortan y una cocina que celebra lo auténtico.\r\n\r\nCada taza de café es preparada con dedicación y pasión, usando granos seleccionados y técnicas que perfeccionamos con el tiempo. Nuestra comida, casera y generosa, acompaña cada visita como si fuera la primera.\r\n\r\nBienvenidos a tu segundo hogar.','Nosotros','','publish','closed','closed','','nosotros','','','2026-06-16 14:45:17','2026-06-16 14:45:17','',0,'http://wp-coffeshop-backend.local/?page_id=24',0,'page','',0);
INSERT INTO `wp_posts` VALUES (25,1,'2026-06-16 14:45:06','2026-06-16 14:45:06','','pagina_nosotros','','inherit','open','closed','','pagina_nosotros','','','2026-06-16 14:45:06','2026-06-16 14:45:06','',24,'http://wp-coffeshop-backend.local/wp-content/uploads/2026/06/pagina_nosotros.jpg',0,'attachment','image/jpeg',0);
INSERT INTO `wp_posts` VALUES (26,1,'2026-06-16 14:45:17','2026-06-16 14:45:17','Desde 1939, el sabor que reúne generaciones\r\n\r\nEn el corazón de la ciudad, nuestra cafetería ha sido testigo de historias, encuentros y momentos memorables desde 1939. Más que un café, ofrecemos una experiencia con alma: aromas que despiertan recuerdos, sabores que reconfortan y una cocina que celebra lo auténtico.\r\n\r\nCada taza de café es preparada con dedicación y pasión, usando granos seleccionados y técnicas que perfeccionamos con el tiempo. Nuestra comida, casera y generosa, acompaña cada visita como si fuera la primera.\r\n\r\nBienvenidos a tu segundo hogar.','Nosotros','','inherit','closed','closed','','24-revision-v1','','','2026-06-16 14:45:17','2026-06-16 14:45:17','',24,'http://wp-coffeshop-backend.local/?p=26',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (27,1,'2026-06-16 18:41:09','2026-06-16 18:41:09','En nuestra cafetería, cada sorbo tiene una historia. Seleccionamos granos de café de origen, los extraemos con cuidado y los tostamos en pequeños lotes para resaltar sus sabores únicos. Aquí, el café no es solo una bebida, es un ritual que comienza desde la finca y termina en tu momento favorito del día.','Proceso','','publish','closed','closed','','proceso','','','2026-06-16 18:55:22','2026-06-16 18:55:22','',0,'http://wp-coffeshop-backend.local/?page_id=27',0,'page','',0);
