INSERT INTO `wp_posts` VALUES (29,1,'2026-06-16 18:41:09','2026-06-16 18:41:09','En nuestra cafetería, cada sorbo tiene una historia. Seleccionamos granos de café de origen, los extraemos con cuidado y los tostamos en pequeños lotes para resaltar sus sabores únicos. Aquí, el café no es solo una bebida, es un ritual que comienza desde la finca y termina en tu momento favorito del día.','Proceso','','inherit','closed','closed','','27-revision-v1','','','2026-06-16 18:41:09','2026-06-16 18:41:09','',27,'http://wp-coffeshop-backend.local/?p=29',0,'revision','',0);
