INSERT INTO `wp_posts` VALUES (56,1,'2026-06-16 18:55:22','2026-06-16 18:55:22','En nuestra cafetería, cada sorbo tiene una historia. Seleccionamos granos de café de origen, los extraemos con cuidado y los tostamos en pequeños lotes para resaltar sus sabores únicos. Aquí, el café no es solo una bebida, es un ritual que comienza desde la finca y termina en tu momento favorito del día.','Proceso','','inherit','closed','closed','','27-revision-v1','','','2026-06-16 18:55:22','2026-06-16 18:55:22','',27,'http://wp-coffeshop-backend.local/?p=56',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (57,1,'2026-06-17 13:28:45','2026-06-17 13:28:45','Nuestra cafetería es más que un buen café: es historias, momentos y detalles que queremos compartir contigo. En esta sección encontrarás nuestro <strong>Blog</strong>, donde hablamos de nuestras recetas, ingredientes favoritos, curiosidades del café y todo lo que hace especial nuestra cocina.','Blog','','publish','closed','closed','','blog','','','2026-06-17 13:28:45','2026-06-17 13:28:45','',0,'http://wp-coffeshop-backend.local/?page_id=57',0,'page','',0);
