INSERT INTO `wp_posts` VALUES (59,1,'2026-06-17 13:28:45','2026-06-17 13:28:45','Nuestra cafetería es más que un buen café: es historias, momentos y detalles que queremos compartir contigo. En esta sección encontrarás nuestro <strong>Blog</strong>, donde hablamos de nuestras recetas, ingredientes favoritos, curiosidades del café y todo lo que hace especial nuestra cocina.','Blog','','inherit','closed','closed','','57-revision-v1','','','2026-06-17 13:28:45','2026-06-17 13:28:45','',57,'http://wp-coffeshop-backend.local/?p=59',0,'revision','',0);
INSERT INTO `wp_posts` VALUES (60,1,'2026-06-17 13:35:10','2026-06-17 13:35:10','Cada taza de café que servimos tiene detrás una historia que comienza mucho antes de llegar a nuestra cafetería. Inicia en fincas donde familias caficultoras recolectan a mano solo los granos más maduros y de mejor calidad.\r\n\r\nLuego, esos granos son secados, clasificados y enviados para ser tostados con precisión, resaltando sus aromas naturales. Este proceso artesanal garantiza que cada grano tenga un sabor único y auténtico.\r\n\r\nNos sentimos orgullosos de trabajar directamente con productores responsables. Así no solo aseguramos calidad, sino que también apoyamos prácticas sostenibles y comercio justo. En cada taza, hay compromiso y respeto por el origen.','De la finca a tu taza: el viaje de nuestros granos','','publish','open','open','','de-la-finca-a-tu-taza-el-viaje-de-nuestros-granos','','','2026-06-17 13:35:10','2026-06-17 13:35:10','',0,'http://wp-coffeshop-backend.local/?p=60',0,'post','',0);
